style.css:
@-moz-document domain("joyland.ai") {
/* Main site background - Standard Magenta */
  body, 
  html, 
  main, 
  [class*="layout"],
  [class*="bg-"] {
    background-color: #ff00ff !important;
  }

  /* Chat messages - Lighter Magenta */
  [class*="message"], 
  [class*="chat-bubble"], 
  [class*="msg-"], 
  [class*="chat-item"], 
  [class*="content-box"] {
    background-color: #ff66ff !important;
    background-image: none !important; /* Removes default gradients */
    color: #ffffff !important;
  }

  /* User messages - Soft/Pastel Light Magenta for clarity */
  [class*="user"], 
  [class*="right-message"] {
    background-color: #ff99ff !important;
    color: #000000 !important;
  }
}

